// assets/film/film_map.json (generated by scripts/film/gen_film_map.py, docs/film/film-map.md) must cover every camera stock
// of the app's name table with x / y in [-1, 1], a known type and the same code as film_names.dart.
import 'dart:convert';
import 'dart:io';

import 'package:dapple/model/film_names.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('film_map.json covers the camera stocks, in range, codes match film_names.dart', () {
    final m = jsonDecode(File('assets/film/film_map.json').readAsStringSync()) as Map<String, dynamic>;
    final stocks = kFilmDisplayNames.keys.where((id) => File('../core/data/film/profiles/$id.json').readAsStringSync().contains('"stage": "filming"'));
    expect(m.keys.toSet(), stocks.toSet());
    for (final e in m.entries) {
      final v = e.value as Map<String, dynamic>;
      expect((v['x'] as num).abs(), lessThanOrEqualTo(1.0));
      expect((v['y'] as num).abs(), lessThanOrEqualTo(1.0));
      expect(['neg', 'rev', 'cine'], contains(v['type']));
      expect(v['code'], kFilmDisplayNames[e.key]);
    }
  });
  test('film_map.json is declared in pubspec.yaml', () {
    expect(File('pubspec.yaml').readAsStringSync(), contains('assets/film/film_map.json'));
  });
}
